import requests, re
ids=['Q05469','Q9R101','Q68J42','P15304','P16386','P54310','P71668','Q8KQK1']
for acc in ids:
    u=f'https://rest.uniprot.org/uniprotkb/{acc}.txt'
    r=requests.get(u,timeout=30)
    print('\n###',acc,r.status_code)
    if r.ok:
        lines=r.text.splitlines()
        for line in lines:
            if line.startswith(('DE   RecName:','DE   AltName:','CC   -!- FUNCTION:','CC   -!- CATALYTIC ACTIVITY:','DR   BRENDA','DR   Rhea','DR   Pfam','FT   ACT_SITE','FT   SITE')):
                print(line)
